{
  "findings": [
    {
      "ref": "[D540]",
      "area": "contact",
      "claim": "A parent reports that users under 13 can no longer directly message others outside of games and must get parental consent to use direct messaging within experiences.",
      "stance": "risk",
      "quote": "users under the age of 13 will no longer able to directly message others on Roblox outside of games or experiences (also known as platform chat). When communicating in a game or experience, users under the age of 13 will be able to communicate using the broadcast public chat. To use direct messaging within experiences, users under 13 will need parental consent."
    },
    {
      "ref": "[D540]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate for under‑13 users is enforced by blocking direct messaging outside games and requiring parental consent for in‑experience direct chat.",
      "stance": "mitigation",
      "quote": "users under the age of 13 will no longer able to directly message others on Roblox outside of games or experiences (also known as platform chat). When communicating in a game or experience, users under the age of 13 will be able to communicate using the broadcast public chat. To use direct messaging within experiences, users under 13 will need parental consent."
    },
    {
      "ref": "[D540]",
      "area": "money",
      "claim": "A parent notes that under‑13 users generally do not have access to credit cards, making the new restrictions seem reasonable.",
      "stance": "neutral",
      "quote": "Generally, people under the age of 13 do not have access to any form of credit card. And given these limitations are (to my understanding) only applied to users of such age it could be seen as reasonable."
    },
    {
      "ref": "[D540]",
      "area": "data",
      "claim": "A parent reports that Roblox no longer allows setting a parent PIN, removing an extra layer of account security.",
      "stance": "risk",
      "quote": "As previously announced over email, as of today, you are no longer able to set or use a parent PIN on your Roblox account."
    },
    {
      "ref": "[D540]",
      "area": "developer_record",
      "claim": "A parent reports that removing the parent PIN was met with disappointment and concerns about security, indicating potential regulatory or reputational risk for the developer.",
      "stance": "risk",
      "quote": "I really wonder why they removed it. I made a on the topic as I feel like it was an important part of developer safety, and even safety in general for EVERY user."
    }
  ]
